8	// View is a read-only derived view of a Roller at a coarser window size.
9	// Each view window covers a fixed number of the roller's own windows and
10	// carries statistics merged from them; no raw samples are re-read. A View
11	// is a snapshot of the moment it was derived: samples filed, backfilled,
12	// or merged into the roller afterwards do not alter it.
13	//
14	// All methods are safe to call concurrently from multiple goroutines.
15	type View struct {
16		// window is the coarse window size: the roller's window size times
17		// the factor the view was derived with. windows is fixed at
18		// derivation and read without a lock.
19		window  time.Duration
20		windows []Window
21	}
22	
23	// Rollup derives a read-only view of the roller whose windows are factor
24	// times wider than the roller's own, aligned to integer multiples of the
25	// coarser size since the Unix epoch, left-closed and right-open exactly
26	// like the roller's windows. Each coarse window merges the statistics of
27	// the roller windows it covers: counts and sums add, minimums take the
28	// smaller, maximums take the larger. A factor of 1 yields a view
29	// window-for-window identical to the roller's own.
30	//
31	// Rollup panics with "rollup: bad factor" if factor is not positive, or if
32	// factor times the roller's window width overflows the range of a
33	// nanosecond duration: a wrapped coarse width could not align windows to
34	// the epoch. It is a pure read: the roller's statistics and its most-recent
35	// marker are untouched, and concurrent adds, batches, backfills, and merges
36	// proceed as usual — the view observes one consistent snapshot of the
37	// roller.
38	func (r *Roller) Rollup(factor int) *View {
39		if factor <= 0 {
40			panic("rollup: bad factor")
41		}
42		if int64(factor) > math.MaxInt64/r.window.Nanoseconds() {
43			panic("rollup: bad factor")
44		}
45		coarse := time.Duration(factor) * r.window
46		w := coarse.Nanoseconds()
47	
48		r.mu.RLock()
49		defer r.mu.RUnlock()
50		fine := r.buckets
51		if len(r.back) != 0 {
52			fine = mergeWindows(r.buckets, r.sortedBackLocked())
53		}
54		// The coarse start is monotone in the fine start, so covered windows
55		// are consecutive and the whole derivation is one linear pass with a
56		// single output allocation bounded by the number of fine windows.
57		windows := make([]Window, 0, len(fine))
58		for _, f := range fine {
59			start := alignStart(f.Start, w)
60			if n := len(windows); n != 0 && windows[n-1].Start.Equal(start) {
61				cur := &windows[n-1]
62				cur.Count = satAdd(cur.Count, f.Count)
63				cur.Sum += f.Sum
64				if f.Min < cur.Min {
65					cur.Min = f.Min
66				}
67				if f.Max > cur.Max {
68					cur.Max = f.Max
69				}
70			} else {
71				windows = append(windows, Window{
72					Start: start,
73					Count: f.Count,
74					Sum:   f.Sum,
75					Min:   f.Min,
76					Max:   f.Max,
77				})
78			}
79		}
80		return &View{window: coarse, windows: windows}
81	}
82	
83	// Window returns the coarse window whose start matches start exactly, by
84	// the same exact-match rule as the roller's Window. A start no coarse
85	// window begins at yields the zero Window and no error; whether the window
86	// exists is told from its sample count. The returned Window is a copy and
87	// stays valid no matter what is filed into the roller afterwards.
88	func (v *View) Window(start time.Time) Window {
89		if i, ok := windowIndex(v.windows, start); ok {
90			return v.windows[i]
91		}
92		return Window{}
93	}
94	
95	// Range returns the coarse windows overlapping the half-open interval
96	// [from, to), in time order, selected by the same rule as the roller's
97	// Range: the first window returned is the one containing from, and a
98	// window starting exactly at to is excluded. An interval whose end does
99	// not come after its start yields an empty slice, as does an interval no
100	// coarse window overlaps.
101	func (v *View) Range(from, to time.Time) []Window {
102		out := []Window{}
103		if !from.Before(to) {
104			return out
105		}
106		i, _ := windowIndex(v.windows, alignStart(from, v.window.Nanoseconds()))
107		for ; i < len(v.windows); i++ {
108			w := v.windows[i]
109			if !w.Start.Before(to) {
110				break
111			}
112			out = append(out, w)
113		}
114		return out
115	}
116	
117	// Cursor returns a cursor over the coarse windows overlapping the
118	// half-open interval [from, to), selected by the same rule as Range. The
119	// view is already a snapshot, so the cursor's batches never tear, skip,
120	// or repeat a window no matter what is filed into the roller while the
121	// cursor advances.
122	func (v *View) Cursor(from, to time.Time) *Cursor {
123		return &Cursor{windows: v.Range(from, to)}
124	}
