1	package rollup
2	
3	import (
4		"math"
5		"math/big"
6		"testing"
7		"time"
8	)
9	
10	// wantStart computes the epoch-aligned window start for at with 128-bit
11	// big-integer arithmetic, as an independent oracle for startOf.
12	func wantStart(at time.Time, w time.Duration) time.Time {
13		ns := big.NewInt(at.Unix())
14		ns.Mul(ns, big.NewInt(1e9))
15		ns.Add(ns, big.NewInt(int64(at.Nanosecond())))
16		wns := big.NewInt(w.Nanoseconds())
17		q := new(big.Int).Quo(ns, wns)
18		if new(big.Int).Rem(ns, wns).Sign() != 0 && ns.Sign() < 0 {
19			q.Sub(q, big.NewInt(1))
20		}
21		start := q.Mul(q, wns)
22		sec := new(big.Int).Quo(start, big.NewInt(1e9))
23		rem := new(big.Int).Rem(start, big.NewInt(1e9))
24		if rem.Sign() != 0 && start.Sign() < 0 {
25			sec.Sub(sec, big.NewInt(1))
26			rem.Add(rem, big.NewInt(1e9))
27		}
28		return time.Unix(sec.Int64(), rem.Int64()).UTC()
29	}
30	
31	// TestExtremeTimestampsAlign checks that samples far outside the int64
32	// nanosecond range still land in epoch-aligned windows.
33	func TestExtremeTimestampsAlign(t *testing.T) {
34		const window = 10 * time.Second
35		for _, at := range []time.Time{
36			time.Unix(1<<62, 123456789),       // far future, UnixNano overflows
37			time.Unix(-1<<62, 987654321),      // far past, UnixNano overflows
38			time.Unix(0, math.MaxInt64),       // largest representable nanos
39			time.Unix(0, math.MinInt64),       // smallest representable nanos
40			time.Unix(-9223372036, 999999999), // fast-path boundary
41			time.Unix(9223372036, 854775807),  // slow-path boundary
42		} {
43			r := New(window)
44			if err := r.Add(at, 5); err != nil {
45				t.Fatalf("Add(%v): %v", at, err)
46			}
47			want := wantStart(at, window)
48			w, ok := r.Window(want)
49			if !ok {
50				t.Fatalf("Add(%v): no window at aligned start %v", at, want)
51			}
52			if w.Count != 1 || w.Sum != 5 || w.Min != 5 || w.Max != 5 {
53				t.Fatalf("Add(%v): window %+v", at, w)
54			}
55			if got := r.Windows(); len(got) != 1 || !got[0].Start.Equal(want) {
56				t.Fatalf("Add(%v): Windows() = %v, want start %v", at, got, want)
57			}
58		}
59	}
60	
61	// TestMinWindowSize checks that a 1-nanosecond window behaves like any
62	// other size: boundary ownership, alignment, and lookup by start.
63	func TestMinWindowSize(t *testing.T) {
64		r := New(1)
65		for _, ns := range []int64{0, 0, 1, 2, 5} {
66			if err := r.Add(time.Unix(0, ns), float64(ns)); err != nil {
67				t.Fatal(err)
68			}
69		}
70		got := r.Windows()
71		if len(got) != 4 {
72			t.Fatalf("want 4 windows, got %d", len(got))
73		}
74		for i, ns := range []int64{0, 1, 2, 5} {
75			if !got[i].Start.Equal(time.Unix(0, ns)) {
76				t.Fatalf("window %d starts at %v, want %v", i, got[i].Start, time.Unix(0, ns))
77			}
78		}
79		w, ok := r.Window(time.Unix(0, 0))
80		if !ok || w.Count != 2 || w.Sum != 0 {
81			t.Fatalf("window 0: %+v ok=%v", w, ok)
82		}
83	}
84	
85	// TestCountSaturates checks that a window count at the int64 ceiling stops
86	// accumulating while sum, min, and max keep updating.
87	func TestCountSaturates(t *testing.T) {
88		r := New(time.Minute)
89		r.buckets = append(r.buckets, Window{
90			Start: time.Unix(0, 0).UTC(),
91			Count: math.MaxInt64,
92			Sum:   10,
93			Min:   1,
94			Max:   9,
95		})
96		r.latest = time.Unix(0, 0)
97		r.hasAny = true
98		if err := r.Add(time.Unix(0, 0), 20); err != nil {
99			t.Fatal(err)
100		}
101		w, _ := r.Window(time.Unix(0, 0))
102		if w.Count != math.MaxInt64 {
103			t.Fatalf("count overflowed: %d", w.Count)
104		}
105		if w.Sum != 30 || w.Min != 1 || w.Max != 20 {
106			t.Fatalf("stats did not keep updating: %+v", w)
107		}
108	}
