357	// TestRollupConcurrentWithWrites derives views while batches are filed
358	// continuously: every derived coarse window must be epoch aligned and
359	// internally consistent, and a batch must appear whole or not at all.
360	// Run with -race to catch data races.
361	func TestRollupConcurrentWithWrites(t *testing.T) {
362		r := New(time.Millisecond)
363		var writers sync.WaitGroup
364		stop := make(chan struct{})
365		for g := 0; g < 4; g++ {
366			writers.Add(1)
367			go func(g int) {
368				defer writers.Done()
369				at := time.Unix(0, 0)
370				for {
371					select {
372					case <-stop:
373						return
374					default:
375					}
376					_ = r.AddBatch([]Sample{
377						{At: at, Value: float64(g)},
378						{At: at.Add(time.Millisecond), Value: float64(g)},
379					})
380					at = at.Add(2 * time.Millisecond)
381				}
382			}(g)
383		}
384		for i := 0; i < 200; i++ {
385			v := r.Rollup(100) // 100ms coarse windows
386			ws := v.Range(time.Unix(-1, 0), time.Unix(1<<30, 0))
387			for j := 1; j < len(ws); j++ {
388				if !ws[j-1].Start.Before(ws[j].Start) {
389					t.Fatalf("coarse windows out of order: %v then %v", ws[j-1].Start, ws[j].Start)
390				}
391			}
392			for _, w := range ws {
393				if w.Start.UnixNano()%(100*time.Millisecond.Nanoseconds()) != 0 {
394					t.Fatalf("misaligned coarse window: %+v", w)
395				}
396				if w.Count <= 0 || w.Min > w.Max {
397					t.Fatalf("torn coarse window: %+v", w)
398				}
399			}
400			// A cursor over the same frozen view must hand out each window once.
401			c := v.Cursor(time.Unix(-1, 0), time.Unix(1<<30, 0))
402			seen := 0
403			for got := c.Next(37); len(got) != 0; got = c.Next(37) {
404				seen += len(got)
405			}
406			if seen != len(ws) {
407				t.Fatalf("cursor saw %d windows, view has %d", seen, len(ws))
408			}
409		}
410		close(stop)
411		writers.Wait()
412	}
413	
414	// BenchmarkRollup measures deriving a coarse view; the cost should scale
415	// linearly with the number of fine windows and the temporary allocation
416	// stay bounded by that number.
417	func BenchmarkRollup(b *testing.B) {
418		for _, n := range []int{1000, 100000} {
419			r := benchRoller(time.Second, n)
420			b.Run(fmt.Sprintf("n=%d/factor=10", n), func(b *testing.B) {
421				b.ReportAllocs()
422				for i := 0; i < b.N; i++ {
423					sinkView = r.Rollup(10)
424				}
425			})
426			b.Run(fmt.Sprintf("n=%d/factor=1", n), func(b *testing.B) {
427				b.ReportAllocs()
428				for i := 0; i < b.N; i++ {
429					sinkView = r.Rollup(1)
430				}
431			})
432		}
433	}
