375	// TestConcurrentAddMergeQueryMillion runs the full mixed workload at the
376	// million scale: concurrent submission, folding merges racing the adds,
377	// and continuous snapshot/query traffic. Every sample is accounted for
378	// exactly once, no window ever tears, and the window set stays ordered.
379	// Run with -race to catch data races.
380	func TestConcurrentAddMergeQueryMillion(t *testing.T) {
381		if testing.Short() {
382			t.Skip("million-sample concurrency run")
383		}
384		r := New(time.Second)
385		const shards = 8
386		const rounds = 15625
387		const batchSize = 8 // 8 * 15625 * 8 = 1,000,000 samples
388	
389		// Every round, all shards file one batch at the same round instant.
390		// Per-round channels synchronize the shards: round r+1 is not
391		// released until every shard finished round r, and equal instants are
392		// always accepted, so all million samples land in round order.
393		starts := make([]chan struct{}, rounds)
394		for i := range starts {
