427					// out exactly once and then end.
428					c := r.Cursor(time.Unix(0, 0), time.Unix(1<<40, 0))
429					for batch := c.Next(4096); len(batch) != 0; batch = c.Next(4096) {
430						for _, w := range batch {
431							if w.Count <= 0 || w.Min > w.Max {
432								t.Errorf("torn cursor window: %+v", w)
433								return
434							}
435						}
436					}
437					if tail := c.Next(8); len(tail) != 0 {
438						t.Errorf("exhausted cursor moved: %+v", tail)
439						return
440					}
441				}
442			}()
443		}
