283	// contract writes to the letter: when the widths differ, the two file
284	// names appear in command-line order, separated by a comma and a space,
285	// on the single stderr diagnostic line. The mismatched-width state is
286	// unreachable through one --window flag, so the formatting unit is
287	// exercised directly.
288	func TestMergeMismatchDiagnostic(t *testing.T) {
289		var stderr bytes.Buffer
290		writeMergeError(&stderr, "first.txt", "second.txt", rollup.ErrWindowMismatch)
291		want := "rollupctl: first.txt, second.txt: rollup: window mismatch\n"
292		if stderr.String() != want {
293			t.Fatalf("stderr = %q, want %q", stderr.String(), want)
294		}
295		if strings.Count(strings.TrimRight(stderr.String(), "\n"), "\n") != 0 {
296			t.Fatalf("stderr must be one line: %q", stderr.String())
297		}
298	}
