func exactSum(vals []float64) float64 {
	acc := new(big.Float)
	acc.SetPrec(64)
	for _, v := range vals {
		var f big.Float
		f.SetPrec(64)
		f.SetFloat64(v)
		acc.Add(acc, &f)
	}
	r, _ := acc.Float64()
	return r
}

func main() {
