package rollup

import (
	"math"
	"math/big"
)

// stats holds the exact bookkeeping behind one Window's Sum, Min, and Max.
// The Window values stay populated on every write and hold the latest
// canonical result; stats keeps what the float64 values alone cannot:
//
//   - rat is the exact real sum of every finite sample filed into the
//     window, as an arbitrary-precision rational. Float64 addition is
//     rounded after every step and therefore depends on submission order;
//     the exact sum does not, so it is rounded to float64 once, at read
//     time, and every interleaving of the same sample set rounds to the
//     same bits.
//   - the zero flags record whether a negative zero (or a positive zero)
//     sample was filed, so the sign of a zero sum and of zero extrema is
//     fixed by the sample set rather than by arithmetic residue.
//   - infMinus/infPlus/nan record that the exact sum has overflowed in the
//     negative/positive direction, or that opposite infinities combine to
//     NaN. No non-finite value is ever filed, so these only arise from
//     overflow and from merging windows that overflowed opposite ways.
//
// A zero stats is not usable; every live one has initialized set. Windows
// built directly in tests bypass the constructors, so a stats seeded from
// such a window absorbs the Window's already-computed Sum on first touch.
type stats struct {
	rat       *big.Rat
	initialized bool
	negZero   bool // the window holds at least one -0 sample
	posZero   bool // the window holds at least one +0 sample
	nonZero   bool // the window holds at least one non-zero sample
	infMinus  bool // the exact sum has overflowed toward -Inf
	infPlus   bool // the exact sum has overflowed toward +Inf
	nan       bool // opposite infinities combine to NaN
}

// negZeroVal is the negative zero float64.
var negZeroVal = math.Copysign(0, -1)

// seedStats returns bookkeeping for a window freshly created from one
// finite sample.
func seedStats(value float64) stats {
	var st stats
	st.initialized = true
	st.accumulate(value)
	return st
}

// accumulate folds one finite sample's value into the exact sum.
func (st *stats) accumulate(value float64) {
	if value == 0 {
		if math.Signbit(value) {
			st.negZero = true
		} else {
			st.posZero = true
		}
		return
	}
	st.nonZero = true
	// Once the exact sum has left the finite range, further finite samples
	// cannot bring it back; stop growing the rational.
	if st.infMinus || st.infPlus || st.nan {
		return
	}
	f, _ := new(big.Rat).SetFloat64(value)
	if st.rat == nil {
		st.rat = f
	} else {
		st.rat.Add(st.rat, f)
	}
}

// absorb seeds bookkeeping from a Window assembled without stats (the
// package's tests build such windows directly). It is called only when a
// stats is still virgin.
func (st *stats) absorb(w Window) {
	st.initialized = true
	switch {
	case math.IsNaN(w.Sum):
		st.nan = true
	case math.IsInf(w.Sum, 1):
		st.infPlus = true
	case math.IsInf(w.Sum, -1):
		st.infMinus = true
	case w.Sum != 0:
		st.nonZero = true
		st.rat, _ = new(big.Rat).SetFloat64(w.Sum)
	}
	// Recover whatever zero signs the stored extrema pin down.
	if w.Min == 0 && math.Signbit(w.Min) {
		st.negZero = true
	}
	if w.Max == 0 && !math.Signbit(w.Max) {
		st.posZero = true
	}
}

// combine folds other's bookkeeping into st, as merging two windows over
// the same start does.
func (st *stats) combine(other *stats) {
	if !other.initialized {
		return
	}
	if !st.initialized {
		*st = *other
		if other.rat != nil {
			st.rat = new(big.Rat).Set(other.rat)
		}
		return
	}
	st.negZero = st.negZero || other.negZero
	st.posZero = st.posZero || other.posZero
	st.nonZero = st.nonZero || other.nonZero
	st.nan = st.nan || other.nan
	st.infMinus = st.infMinus || other.infMinus
	st.infPlus = st.infPlus || other.infPlus
	if st.infMinus && st.infPlus {
		// Opposite infinities add to NaN.
		st.nan = true
		st.rat = nil
		return
	}
	switch {
	case st.rat != nil && other.rat != nil:
		st.rat.Add(st.rat, other.rat)
	case other.rat != nil:
		st.rat = new(big.Rat).Set(other.rat)
	}
}

// canonicalSum rounds the exact sum to the float64 value the contract
// fixes: NaN from opposite infinities, +/-Inf from one-sided overflow, a
// signed zero only when every sample was a zero of that sign, and
// otherwise the nearest float64 to the exact sum.
func (st *stats) canonicalSum() float64 {
	switch {
	case st.nan || (st.infMinus && st.infPlus):
		return math.NaN()
	case st.infPlus:
		return math.Inf(1)
	case st.infMinus:
		return math.Inf(-1)
	case !st.nonZero:
		if st.negZero && !st.posZero {
			return negZeroVal
		}
		return 0
	}
	v, _ := st.rat.Float64()
	switch {
	case math.IsInf(v, 1):
		st.infPlus = true
		st.rat = nil
		return math.Inf(1)
	case math.IsInf(v, -1):
		st.infMinus = true
		st.rat = nil
		return math.Inf(-1)
	}
	return v
}

// canonicalMin fixes a minimum that is zero: it is a negative zero when
// the window holds a negative-zero sample, and a positive zero otherwise.
// A strictly negative minimum keeps its value.
func canonicalMin(v float64, negZero bool) float64 {
	if v == 0 && negZero {
		return negZeroVal
	}
	return v
}

// canonicalMax fixes a maximum that is zero: it is a negative zero only
// when every zero sample was a negative zero and there was no positive
// zero; with a positive zero present, or a strictly positive maximum, it
// is positive.
func canonicalMax(v float64, negZero, posZero bool) float64 {
	if v == 0 && negZero && !posZero {
		return negZeroVal
	}
	return v
}

// reconcile returns a stats slice aligned one-for-one with ws, seeding any
// virgin entry (including a missing or short slice) from its window.
func reconcile(ws []Window, ss []stats) []stats {
	if len(ss) < len(ws) {
		grown := make([]stats, len(ws))
		copy(grown, ss)
		ss = grown
	}
	for i := range ws {
		if !ss[i].initialized {
			ss[i].absorb(ws[i])
		}
	}
	return ss
}

// addTo folds one finite sample into w and its bookkeeping st. Count
// saturates at math.MaxInt64 instead of overflowing; the sum and extrema
// keep updating afterwards under their fixed semantics.
func addTo(w *Window, st *stats, value float64) {
	if w.Count < math.MaxInt64 {
		w.Count++
	}
	st.accumulate(value)
	if value < w.Min {
		w.Min = value
	}
	if value > w.Max {
		w.Max = value
	}
	w.Sum = st.canonicalSum()
	w.Min = canonicalMin(w.Min, st.negZero)
	w.Max = canonicalMax(w.Max, st.negZero, st.posZero)
}

// combineWindow folds src into dst as merging two windows over the same
// start does: counts saturate, the exact sums combine, and the extrema
// take the smaller minimum and larger maximum under the zero-sign rules.
func combineWindow(dst *Window, dstSt, src *Window, srcSt *stats) {
	dst.Count = satAdd(dst.Count, src.Count)
	dstSt.combine(srcSt)
	if src.Min < dst.Min {
		dst.Min = src.Min
	}
	if src.Max > dst.Max {
		dst.Max = src.Max
	}
	dst.Sum = dstSt.canonicalSum()
	dst.Min = canonicalMin(dst.Min, dstSt.negZero)
	dst.Max = canonicalMax(dst.Max, dstSt.negZero, dstSt.posZero)
}

// canonicalWindow applies the fixed sum and extrema semantics to w.
func canonicalWindow(w Window, st *stats) Window {
	if !st.initialized {
		return w
	}
	w.Sum = st.canonicalSum()
	w.Min = canonicalMin(w.Min, st.negZero)
	w.Max = canonicalMax(w.Max, st.negZero, st.posZero)
	return w
}

