// maybeFlushBack folds the backfilled windows into buckets once they
// number at least half as many as buckets, so the sorting and merge cost
// amortizes to constant time per backfilled window. The caller must hold
// mu.
func (r *Roller) maybeFlushBack() {
	if len(r.back)*2 < len(r.buckets) {
		return
	}
	bw, bs := r.sortedBackLocked()
	r.buckets, r.bstats = mergeWindows(r.buckets, r.bstats, bw, bs)
	r.back = nil
}

// sortedBackLocked returns the backfilled windows in time order. The
// caller must hold mu; the returned slices are fresh and aligned and each
// stats owns an independent rational.
func (r *Roller) sortedBackLocked() ([]Window, []stats) {
	starts := make([]time.Time, 0, len(r.back))
	for s := range r.back {
		starts = append(starts, s)
	}
	sort.Slice(starts, func(i, j int) bool {
		return starts[i].Before(starts[j])
	})
	ws := make([]Window, len(starts))
	ss := make([]stats, len(starts))
	for i, s := range starts {
		bw := r.back[s]
		ws[i] = bw.w
		ss[i] = cloneStats(bw.st)
	}
	return ws, ss
}

// sortedBackWindowsLocked returns just the backfilled windows in time
// order for reads that only display statistics already stored on them.
func (r *Roller) sortedBackWindowsLocked() []Window {
	starts := make([]time.Time, 0, len(r.back))
	for s := range r.back {
		starts = append(starts, s)
	}
	sort.Slice(starts, func(i, j int) bool {
		return starts[i].Before(starts[j])
	})
	ws := make([]Window, len(starts))
	for i, s := range starts {
		ws[i] = r.back[s].w
	}
	return ws
}

// interleaveWindows returns the time-ordered union of two window slices,
// each sorted by start. A start shared by both is combined by fn; reads
// use it only for buckets plus the backfill map, whose starts are disjoint
// by construction, so fn is only exercised on the write paths.
func interleaveWindows(a, b []Window, fn func(Window, Window) Window) []Window {
	merged := make([]Window, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		switch {
		case a[i].Start.Before(b[j].Start):
			merged = append(merged, a[i])
			i++
		case b[j].Start.Before(a[i].Start):
			merged = append(merged, b[j])
			j++
		default:
			merged = append(merged, fn(a[i], b[j]))
			i++
			j++
		}
	}
	merged = append(merged, a[i:]...)
	merged = append(merged, b[j:]...)
	return merged
}

// orderedWindowsLocked returns every window in time order as a fresh
// Window slice. Buckets and the backfill map hold disjoint starts, so no
// statistics are recombined on this display-only path.
func (r *Roller) orderedWindowsLocked() []Window {
	if len(r.back) == 0 {
		out := make([]Window, len(r.buckets))
		copy(out, r.buckets)
		return out
	}
	return interleaveWindows(r.buckets, r.sortedBackWindowsLocked(), nil)
}

