cat > rollup/zz_scratch_test.go <<'EOF'
package rollup

import (
	"errors"
	"fmt"
	"math"
	"testing"
	"time"
)

func TestScratchSemantics(t *testing.T) {
	nz := math.Copysign(0, -1)
	// 1. Order-independent sum via batches/permutations.
	order1 := func() float64 {
		r := New(time.Minute)
		r.AddBatch([]Sample{{time.Unix(0, 0), 1e20}, {time.Unix(0, 0), 1}, {time.Unix(0, 0), -1e20}})
		w, _ := r.Window(time.Unix(0, 0))
		return w.Sum
	}
	order2 := func() float64 {
		r := New(time.Minute)
		r.Add(time.Unix(0, 0), -1e20)
		r.Add(time.Unix(0, 0), 1)
		r.Add(time.Unix(0, 0), 1e20)
		w, _ := r.Window(time.Unix(0, 0))
		return w.Sum
	}
	s1, s2 := order1(), order2()
	fmt.Println("sum permutations:", s1, s2, "bits equal:", math.Float64bits(s1) == math.Float64bits(s2))

	// 2. Zero signs.
	cases := []struct {
		name string
		vals []float64
		sum  float64
		min  float64
		max  float64
	}{
		{"all neg zero", []float64{nz, nz}, nz, nz, nz},
		{"neg and pos zero", []float64{nz, 0}, 0, nz, 0},
		{"all pos zero", []float64{0, 0}, 0, 0, 0},
		{"negzero then +1", []float64{nz, 1}, 1, nz, 1},
		{"+1 then negzero", []float64{1, nz}, 1, nz, 1},
		{"-1 then negzero", []float64{-1, nz}, -1, -1, nz},
		{"negzero and -1", []float64{nz, -1}, -1, -1, nz},
		{"negzero poszero -1", []float64{nz, 0, -1}, -1, -1, 0},
	}
	for _, c := range cases {
		r := New(time.Minute)
		for _, v := range c.vals {
			if err := r.Add(time.Unix(0, 0), v); err != nil {
				t.Fatalf("%s: %v", c.name, err)
			}
		}
		w, _ := r.Window(time.Unix(0, 0))
		eq := func(a, b float64) bool { return math.Float64bits(a) == math.Float64bits(b) }
		if !eq(w.Sum, c.sum) || !eq(w.Min, c.min) || !eq(w.Max, c.max) {
			t.Errorf("%s: got sum %v(%b) min %v max %v; want sum %v min %v max %v",
				c.name, w.Sum, math.Float64bits(w.Sum), w.Min, w.Max, c.sum, c.min, c.max)
		}
	}

	// 3. Overflow and NaN via merge.
	pos := New(time.Minute)
	pos.Add(time.Unix(0, 0), math.MaxFloat64)
	pos.Add(time.Unix(0, 0), math.MaxFloat64)
	w, _ := pos.Window(time.Unix(0, 0))
	fmt.Println("overflow sum:", w.Sum, "is +inf:", math.IsInf(w.Sum, 1))
	// Add a large negative finite sample: exact lineage recovers to finite Max.
	pos.Add(time.Unix(0, 0), -math.MaxFloat64)
	w, _ = pos.Window(time.Unix(0, 0))
	fmt.Println("after -Max (exact lineage):", w.Sum, "== Max:", w.Sum == math.MaxFloat64)
	// Merge opposite overflow -> NaN.
	neg := New(time.Minute)
	neg.Add(time.Unix(0, 0), -math.MaxFloat64)
	neg.Add(time.Unix(0, 0), -math.MaxFloat64)
	wn, _ := neg.Window(time.Unix(0, 0))
	fmt.Println("neg overflow:", wn.Sum, "is -inf:", math.IsInf(wn.Sum, -1))
	merged := New(time.Minute)
	merged.Add(time.Unix(0, 0), math.MaxFloat64)
	merged.Add(time.Unix(0, 0), math.MaxFloat64)
	merged.Merge(neg)
	wm, _ := merged.Window(time.Unix(0, 0))
	fmt.Println("opposite inf merge:", wm.Sum, "isNaN:", math.IsNaN(wm.Sum))

	// 4. Non-finite rejection.
	r := New(time.Minute)
	if err := r.Add(time.Unix(0, 0), math.NaN()); !errors.Is(err, ErrNonFinite) {
		t.Fatalf("NaN Add: %v", err)
	}
	if err := r.Add(time.Unix(0, 0), math.Inf(1)); !errors.Is(err, ErrNonFinite) {
		t.Fatalf("+Inf Add: %v", err)
	}
	if err := r.Add(time.Unix(0, 0), math.Inf(-1)); !errors.Is(err, ErrNonFinite) {
		t.Fatalf("-Inf Add: %v", err)
	}
	if got := r.Windows(); len(got) != 0 {
		t.Fatalf("rejected non-finite changed state: %v", got)
	}
	// marker not advanced by rejected non-finite
	if err := r.Add(time.Unix(100, 0), 1); err != nil {
		t.Fatalf("marker moved: %v", err)
	}
	if err := r.AddBatch([]Sample{{time.Unix(200, 0), 1}, {time.Unix(150, 0), math.NaN()}}); !errors.Is(err, ErrNonFinite) {
		t.Fatalf("batch NaN: %v", err)
	}
	if got := r.Windows(); len(got) != 1 {
		t.Fatalf("rejected batch changed state: %d", len(got))
	}
	// non-finite before a stale sample: which error? contract says any reject; NaN scanned first.
	if err := r.AddBatch([]Sample{{time.Unix(50, 0), math.Inf(1)}}); !errors.Is(err, ErrNonFinite) {
		t.Fatalf("batch stale+inf: %v", err)
	}
	fmt.Println("rejection OK")
}
EOF
