	if !bitsEq(w0.Sum, negZero) || !bitsEq(w0.Min, negZero) || !bitsEq(w0.Max, negZero) {
		t.Fatalf("all-negative-zero window after merge: %+v", w0)
	}
	w1, _ := a.Window(time.Unix(60, 0))
	if !math.IsNaN(w1.Sum) {
