	}
}

// TestViewCoarseInfinity checks that a derived view combines covered
// windows with the same infinity rules as merging: one-sided overflow is
// infinite, opposite overflows are NaN, and all-negative-zero coarse
// windows keep their sign.
func TestViewCoarseInfinityAndZeros(t *testing.T) {
	r := New(time.Second)
	// Two fine windows overflowing opposite ways, both inside one 3s
	// coarse window.
	r.Add(time.Unix(0, 0), math.MaxFloat64)
	r.Add(time.Unix(0, 0), math.MaxFloat64)
	r.Add(time.Unix(1, 0), -math.MaxFloat64)
	r.Add(time.Unix(1, 0), -math.MaxFloat64)
	// An all-negative-zero window in the next coarse window.
	r.Add(time.Unix(3, 0), negZero)
	v := r.Rollup(3)
	w := v.Window(time.Unix(0, 0))
	if !math.IsNaN(w.Sum) {
		t.Fatalf("coarse opposite infinities: %+v", w)
	}
	z := v.Window(time.Unix(3, 0))
	if !bitsEq(z.Sum, negZero) || !bitsEq(z.Min, negZero) || !bitsEq(z.Max, negZero) {
		t.Fatalf("coarse all-negative-zero: %+v", z)
	}
}

// TestDeterminismUnderMerge checks that merging the same two sets in
// different histories yields identical stats per window.
func TestDeterminismUnderMerge(t *testing.T) {
	mk := func(vals ...float64) *Roller {
		r := New(time.Minute)
		for i, v := range vals {
			if err := r.Add(time.Unix(int64(i)*60, 0), v); err != nil {
				panic(err)
			}
		}
		return r
	}
	snap := func(r *Roller) []Window {
		ws := r.Windows()
		sort.Slice(ws, func(i, j int) bool { return ws[i].Start.Before(ws[j].Start) })
		return ws
	}
	first := snap(func() *Roller {
		a := mk(1e20, -1e20, 5)
		b := mk(1, 150000)
		a.Merge(b)
		return a
	}())
	second := snap(func() *Roller {
		a := mk(5)
		b := mk(1, 150000)
		c := New(time.Minute)
		c.Add(time.Unix(0, 0), 1e20)
		c.Add(time.Unix(0, 0), -1e20)
		a.Merge(b)
		a.Merge(c)
		return a
	}())
	if len(first) != len(second) {
		t.Fatalf("window counts differ: %v vs %v", first, second)
	}
	for i := range first {
		if first[i].Start != second[i].Start || first[i].Count != second[i].Count ||
			!bitsEq(first[i].Sum, second[i].Sum) ||
			!bitsEq(first[i].Min, second[i].Min) ||
			!bitsEq(first[i].Max, second[i].Max) {
			t.Fatalf("window %d: %+v vs %+v", i, first[i], second[i])
		}
	}
	_ = fmt.Sprint
}

