// combine folds other's bookkeeping into st, as merging two windows over
// the same start does. Two exact lineages stay exact; an infinity on
// either side combines by the IEEE rules (+Inf with -Inf is NaN) and then
// sticks, as rounded sums combined by a merge do.
func (st *stats) combine(other *stats) {
	if !other.initialized {
		return
	}
	if !st.initialized {
		*st = *other
		if other.sum != nil {
			st.sum = new(big.Int).Set(other.sum)
		}
		return
	}
	st.negZero = st.negZero || other.negZero
	st.posZero = st.posZero || other.posZero
	st.nonZero = st.nonZero || other.nonZero

	ka, kb := st.kindOf(), other.kindOf()
	switch {
	case ka == kindNaN || kb == kindNaN:
		st.nan = true
		st.sum = nil
	case ka == kindPlusInf && kb == kindMinusInf, ka == kindMinusInf && kb == kindPlusInf:
		st.nan = true
		st.sum = nil
	case ka == kindPlusInf || kb == kindPlusInf:
		st.infPlus = true
		st.infMinus, st.nan = false, false
		st.sum = nil
	case ka == kindMinusInf || kb == kindMinusInf:
		st.infMinus = true
		st.infPlus, st.nan = false, false
		st.sum = nil
	default:
		// Both sides finite: the union stays exact at the finer scale.
		st.infMinus, st.infPlus, st.nan = false, false, false
		switch {
		case st.sum == nil && other.sum != nil:
			st.sum = new(big.Int).Set(other.sum)
			st.scale = other.scale
		case st.sum != nil && other.sum != nil:
			target := st.scale
			if other.scale < target {
				target = other.scale
			}
			tmp := intPool.Get().(*big.Int)
			if other.scale == target {
				tmp.Set(other.sum)
			} else {
				tmp.Lsh(other.sum, uint(other.scale-target))
			}
			if st.scale != target {
				st.sum.Lsh(st.sum, uint(st.scale-target))
				st.scale = target
			}
			st.sum.Add(st.sum, tmp)
			intPool.Put(tmp)
		}
	}
}

// double folds a window's sum state with itself, as merging a roller into
// itself does.
func (st *stats) double() {
	switch st.kindOf() {
	case kindFinite:
		if st.sum != nil {
			st.sum.Lsh(st.sum, 1)
		}
	case kindPlusInf:
		st.infPlus = true
		st.sum = nil
	case kindMinusInf:
		st.infMinus = true
		st.sum = nil
	case kindNaN:
		st.nan = true
		st.sum = nil
	}
}

input.new_string:
// combine folds other's bookkeeping into st, as merging two windows over
// the same start does. Windows grown from real samples both carry an
// exact integer, so their union stays exact however large it rounds; a
// sticky NaN or infinity can only come from a window assembled directly
// with a non-finite Sum, and then the two rounded sums combine by the
// IEEE rules (+Inf with -Inf is NaN, an infinity absorbs finite values).
func (st *stats) combine(other *stats) {
	if !other.initialized {
		return
	}
	if !st.initialized {
		*st = *other
		if other.sum != nil {
			st.sum = new(big.Int).Set(other.sum)
		}
		return
	}
	st.negZero = st.negZero || other.negZero
	st.posZero = st.posZero || other.posZero
	st.nonZero = st.nonZero || other.nonZero

	switch {
	case st.sum != nil && other.sum != nil:
		// Two exact lineages: the union is exact at the finer scale.
		target := st.scale
		if other.scale < target {
			target = other.scale
		}
		tmp := intPool.Get().(*big.Int)
		if other.scale == target {
			tmp.Set(other.sum)
		} else {
			tmp.Lsh(other.sum, uint(other.scale-target))
		}
		if st.scale != target {
			st.sum.Lsh(st.sum, uint(st.scale-target))
			st.scale = target
		}
		st.sum.Add(st.sum, tmp)
		intPool.Put(tmp)
		st.infMinus, st.infPlus, st.nan = false, false, false
	case other.sum != nil:
		// st is a sticky rounded sum (or a zero-only window).
		st.combineSticky(other)
		st.sum = st.combineExact(other)
	default:
		// other is sticky or zero-only; fold it into st.
		st.combineSticky(other)
	}
}

// combineExact returns an integer for an exact other folded into a sticky
// or zero-only st, or nil when the sticky result must remain non-finite.
// The caller has already updated the sticky flags via combineSticky.
func (st *stats) combineExact(other *stats) *big.Int {
	if st.infMinus || st.infPlus || st.nan {
		return nil
	}
	// st carried no non-finite rounded sum: adopt the exact other value.
	s := new(big.Int).Set(other.sum)
	st.scale = other.scale
	return s
}

// combineSticky folds other into st when at least one side has no exact
// integer, updating the sticky nan/inf flags and the zero flags. A
// zero-only window (sum nil, no non-finite flag) contributes 0.
func (st *stats) combineSticky(other *stats) {
	ka, kb := st.stickyKind(), other.stickyKind()
	switch {
	case ka == kindNaN || kb == kindNaN:
		st.setSticky(kindNaN)
	case ka == kindPlusInf && kb == kindMinusInf, ka == kindMinusInf && kb == kindPlusInf:
		st.setSticky(kindNaN)
	case ka == kindPlusInf || kb == kindPlusInf:
		st.setSticky(kindPlusInf)
	case ka == kindMinusInf || kb == kindMinusInf:
		st.setSticky(kindMinusInf)
	default:
		st.infMinus, st.infPlus, st.nan = false, false, false
		if st.sum == nil {
			st.sum = nil
		}
	}
}

// setSticky forces the named non-finite sticky state and drops the exact
// integer.
func (st *stats) setSticky(k sumKind) {
	st.sum = nil
	switch k {
	case kindNaN:
		st.nan, st.infPlus, st.infMinus = true, false, false
	case kindPlusInf:
		st.nan, st.infPlus, st.infMinus = false, true, false
	case kindMinusInf:
		st.nan, st.infPlus, st.infMinus = false, false, true
	}
}

// stickyKind reports a side's rounded sum when it has no exact integer:
// a non-finite sticky flag or the finite zero a zero-only window holds.
func (st *stats) stickyKind() sumKind {
	switch {
	case st.nan:
		return kindNaN
	case st.infPlus:
		return kindPlusInf
	case st.infMinus:
		return kindMinusInf
	default:
		return kindFinite
	}
}

// double folds a window's sum with itself, as merging a roller into
// itself does. An exact integer doubles exactly; a sticky non-finite sum
// follows the IEEE rules (+Inf doubled is +Inf, NaN doubled is NaN).
func (st *stats) double() {
	if st.sum != nil {
		st.sum.Lsh(st.sum, 1)
		return
	}
	switch st.stickyKind() {
	case kindPlusInf:
